// Handler function types: void (*)(void)
static void fork_prep(void) { /* Lock mutexes/Acquire state */ }
static void fork_parent(void) { /* Unlock mutexes (Parent process) */ }
static void fork_child(void) { /* Reset state (Child process) */ }

// Register handlers (Must be done before multithreaded fork())
int status = pthread_atfork(fork_prep,
                            fork_parent,
                            fork_child);

